create table ear_drop_applications(
  application_date date, /* "night of" date, so midnight from D to D + 1 counts as date D */
  side enum('left','right'),
  ear_drop_brand enum('Ear Wax MD'), /* may need to switch to foreign key if the list grows */
  hearing_deficit_immediately_before_on_applied_side boolean, /* more details in notes column */
  hearing_deficit_immediately_after_on_applied_side boolean, /* more details in notes column */
  hearing_deficit_in_days_before_on_applied_side boolean, /* more details in notes column */
  hearing_deficit_in_days_after_on_applied_side boolean, /* more details in notes column */
  visible_wax_removal_stages enum('none','lying down only','irrigation only','lying down and irrigation both'),
  photo_coverage boolean,
  notes varchar(2000),
  primary key (application_date, side)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

insert into ear_drop_applications(application_date, side, ear_drop_brand, hearing_deficit_immediately_before_on_applied_side, hearing_deficit_immediately_after_on_applied_side, hearing_deficit_in_days_before_on_applied_side, hearing_deficit_in_days_after_on_applied_side, visible_wax_removal_stages, photo_coverage, notes) values
  ('2024-12-24','left','Ear Wax MD',true,true,true,true,'lying down only',false,'This was my first application of Ear Wax MD. It was motivated by significant hearing discrepancies between my left and right ears that I suspected were due to earwax accumulation. While some earwax did come off, there was no measurable improvement to my left ear hearing. Since earwax removal by an audiologist would eventually address my left ear hearing deficit, in hindsight it appears that this application just didn''t make a big enough dent in the problem. This might partly be because the earwax accumulation was significant, and it might be because I didn''t apply the whole tube and my technique was not good enough in other ways.https://github.com/vipulnaik/diet-exercise-health/blob/master/events/2024/2024-11-29-reduced-hearing-in-left-ear.md#execution-of-eardrop-application-in-left-ear has more information on the application process, hearing tests before and after, and other surrounding context.'),
  ('2025-12-25','left','Ear Wax MD',false,false,true,true,'lying down only',true,'This was the first of two rounds of application of Ear Eax MD for a mild hearing deficit in my left ear that tended to vary through the day, generally being higher in the morning and in many cases clearing by night. On the day of application, there was no hearing deficit immediately before or after application (both of which were at night, when things had cleared up), so the evaluation requires looking at the deficit in the days before and after application. After the application of ear drops, the deficit persisted and the intra-day fluctuation in the deficit reduced, and it is unclear if the application had any clear positive effect on its own. See https://github.com/vipulnaik/diet-exercise-health/blob/master/events/2025/2025-12-22-reduced-hearing-in-left-ear.md#earwax-removal-review-of-last-years-effort-in-preparation-for-trying-again-this-year for more details on the preparation for earwax removal and then the actual application and followup evaluation.'),
  ('2026-01-03','left','Ear Wax MD',true,false,true,true,'lying down and irrigation both',true,'This was the second of two rounds of application of Ear Wax MD for a mild hearing deficit in my left ear. Relatively more earwax came out in this round than in the first round, and this was also the first time that at-home earwax removal seemed directly causal in improving my left ear hearing: an imbalance of about 2/64 measured before the removal narrowed to zero after the removal, and seemingly caused by the removal. However, a small hearing deficit in the left ear was back when I measured the next morning after waking up. However, starting 2026-01-09, all minimum audible volume and balance tests passed, suggesting that the left ear hearing deficit had been addressed. The role of earwax removal via ear drops versus organic clearing is hard to separate. See https://github.com/vipulnaik/diet-exercise-health/blob/master/events/2025/2025-12-22-reduced-hearing-in-left-ear.md#continued-monitoring-of-reduced-hearing-issues-over-the-next-few-days-and-second-application-of-earwax-on-2026-01-04-overnight-from-2026-01-03 onward for the decision to apply Ear Wax MD a second time, the application process, and the before/after hearing results.'),
  ('2026-04-06','right','Ear Wax MD',false,false,false,false,'lying down only',true,'This was my first ear drop application in my right ear. It was not in response to any hearing deficit, but rather, an experimental first of what I hoped would be a practice of periodic application of ear drops in each ear, with somewhat higher frequency in the left ear compared to the right ear given the track record of the left ear having more of a hearing deficit. This was also not during peak winter season when earwax-related hearing deficits have tended to happen. I only got earwax bubbling through as part of the wiping I did when lying down. The additional irrigation step at the end didn''t yield any additional earwax (so the lack of photos just reflects that no wax came off, rather than the photos being missing). Since this was not part of a hearing deficit incident, there is no separate document on it; the only notes are Slack self-chat logs, this SQL entry, and some discussion in https://claude.ai/chat/0afeed5f-bc22-4411-9658-8426e77de3a3 (private Claude conversation, search `When I apply Ear Wax MD`).');
